```javascript
function bubbleSort(arr) {
  // 获取数组的长度
  let len = arr.length;
  // 外层循环，控制比较的轮数
  for (let i = 0; i < len - 1; i++) {
    // 内层循环，控制每轮比较的次数
    for (let j = 0; j < len - 1 - i; j++) {
      // 如果相邻的两个元素顺序不对，就交换它们的位置
      if (arr[j] > arr[j + 1]) {
        // 使用解构赋值来交换元素
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
      }
    }
  }
  // 返回排序后的数组
  return arr;
}
```

